import { test, expect } from '@playwright/test';

test.describe('Incorrect Password Error Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display error message when entering incorrect password', async ({ page }) => {
    // Verify email input is visible
    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toBeVisible();

    // Enter valid email
    await emailInput.fill('user@example.com');

    // Enter incorrect password
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('wrongpassword123');

    // Click login button
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Wait for error message to appear
    await page.waitForTimeout(500);

    // Verify error message is visible
    const errorMessage = page.getByText('Incorrect password');
    await expect(errorMessage).toBeVisible();

    // Verify error message contains specific text
    await expect(errorMessage).toContainText('Incorrect password');

    // Verify login button is still visible
    await expect(loginButton).toBeVisible();
  });

  test('should clear error message when correcting password', async ({ page }) => {
    // Enter valid email
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('user@example.com');

    // Enter incorrect password
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('wrongpassword123');

    // Click login button to trigger error
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Verify error message is visible
    const errorMessage = page.getByText('Incorrect password');
    await expect(errorMessage).toBeVisible();

    // Correct the password
    await passwordInput.fill('correctpassword123');

    // Click login button again
    await loginButton.click();

    // Wait for error message to clear
    await page.waitForTimeout(500);

    // Verify error message is no longer visible
    await expect(errorMessage).not.toBeVisible();

    // Verify login button is still visible
    await expect(loginButton).toBeVisible();
  });
});
